CREATE OR REPLACE FUNCTION heimdall.assign_record_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    -- Callers cannot preserve or choose a revision, even after delete/recreate.
    NEW.revision := nextval('heimdall.record_revision_seq');
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall.guard_decision_resolution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.resolution <> 'pending' THEN
            RAISE EXCEPTION 'decision must start pending' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.product_id, NEW.environment, NEW.decision_id, NEW.request_event_id, NEW.requested_at)
        IS DISTINCT FROM (OLD.product_id, OLD.environment, OLD.decision_id, OLD.request_event_id, OLD.requested_at) THEN
        RAISE EXCEPTION 'immutable decision request' USING ERRCODE = '23514';
    END IF;
    IF OLD.resolution <> 'pending' AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'immutable decision resolution' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_capacity.account_event_charge()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP='INSERT' THEN
        UPDATE heimdall_capacity.policy SET used_events=used_events+1,
          used_bytes=used_bytes+NEW.envelope_bytes,used_deliveries=used_deliveries+NEW.delivery_rows WHERE singleton;
    ELSE
        UPDATE heimdall_capacity.policy SET used_events=used_events-1,
          used_bytes=used_bytes-OLD.envelope_bytes,used_deliveries=used_deliveries-OLD.delivery_rows WHERE singleton;
    END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'missing capacity policy' USING ERRCODE='23514'; END IF;
    RETURN NULL;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_capacity.account_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.resolution<>'pending' THEN RETURN NULL; END IF;
        UPDATE heimdall_capacity.policy SET reserved_events=reserved_events+2,
          reserved_bytes=reserved_bytes+3000000,reserved_deliveries=reserved_deliveries+64 WHERE singleton;
    ELSIF OLD.resolution='pending' AND NEW.resolution<>'pending' THEN
        UPDATE heimdall_capacity.policy SET reserved_events=reserved_events-2,
          reserved_bytes=reserved_bytes-3000000,reserved_deliveries=reserved_deliveries-64 WHERE singleton;
    ELSE RETURN NULL;
    END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'missing capacity policy' USING ERRCODE='23514'; END IF;
    RETURN NULL;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_capacity.guard_charged_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP='UPDATE' THEN
        IF (NEW.product_id,NEW.environment,NEW.event_id,NEW.sink_id)
          IS DISTINCT FROM (OLD.product_id,OLD.environment,OLD.event_id,OLD.sink_id) THEN
            RAISE EXCEPTION 'immutable delivery identity' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    PERFORM singleton FROM heimdall_capacity.policy FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'missing capacity policy' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM heimdall_capacity.event_charges
      WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=NEW.event_id) THEN
        RAISE EXCEPTION 'cannot add a sink after charging an event' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_capacity.guard_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'capacity policy cannot be deleted' USING ERRCODE='23514'; END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.state<>'preparing' OR NEW.used_events<>0 OR NEW.used_bytes<>0 OR NEW.used_deliveries<>0
          OR NEW.reserved_events<>0 OR NEW.reserved_bytes<>0 OR NEW.reserved_deliveries<>0
          OR EXISTS(SELECT 1 FROM heimdall_capacity.event_charges)
          OR EXISTS(SELECT 1 FROM heimdall_capacity.reservations) THEN
            RAISE EXCEPTION 'capacity policy must start empty and preparing' USING ERRCODE='23514';
        END IF;
    ELSIF pg_trigger_depth()<2 AND
      (NEW.used_events,NEW.used_bytes,NEW.used_deliveries,NEW.reserved_events,NEW.reserved_bytes,NEW.reserved_deliveries)
      IS DISTINCT FROM (OLD.used_events,OLD.used_bytes,OLD.used_deliveries,OLD.reserved_events,OLD.reserved_bytes,OLD.reserved_deliveries) THEN
        RAISE EXCEPTION 'capacity counters derive from charges and reservations' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_capacity.guard_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE slot record;
BEGIN
    IF TG_OP='DELETE' THEN
        IF OLD.resolution='pending' THEN RAISE EXCEPTION 'unresolved reservation' USING ERRCODE='23514'; END IF;
        RETURN OLD;
    END IF;
    SELECT request_event_id,resolution,terminal_event_id INTO STRICT slot FROM heimdall.audit_decisions
      WHERE product_id=NEW.product_id AND environment=NEW.environment AND decision_id=NEW.decision_id;
    IF NEW.request_event_id IS DISTINCT FROM slot.request_event_id OR NEW.resolution IS DISTINCT FROM slot.resolution
       OR NEW.terminal_event_id IS DISTINCT FROM slot.terminal_event_id THEN
        RAISE EXCEPTION 'reservation decision binding' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.resolution<>'pending' AND NOT EXISTS(SELECT 1 FROM heimdall_capacity.policy WHERE singleton AND state='preparing') THEN
            RAISE EXCEPTION 'resolved import requires offline preparation' USING ERRCODE='23514';
        END IF;
    ELSE
        IF (NEW.product_id,NEW.environment,NEW.decision_id,NEW.request_event_id)
          IS DISTINCT FROM (OLD.product_id,OLD.environment,OLD.decision_id,OLD.request_event_id)
          OR (OLD.resolution<>'pending' AND NEW IS DISTINCT FROM OLD) THEN
            RAISE EXCEPTION 'immutable reservation binding or resolution' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_capacity.prepare_event_charge()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP='UPDATE' THEN
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'immutable event charge' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    PERFORM singleton FROM heimdall_capacity.policy FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'missing capacity policy' USING ERRCODE='23514'; END IF;
    SELECT octet_length(event::text) INTO STRICT NEW.envelope_bytes
      FROM heimdall.audit_events WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=NEW.event_id;
    SELECT count(*) INTO NEW.delivery_rows FROM heimdall.audit_deliveries
      WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=NEW.event_id;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_retention.charge_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE used_delta bigint:=0; reserved_delta bigint:=0; members bigint;
BEGIN
    IF octet_length(to_jsonb(NEW)::text)>8192 THEN
        RAISE EXCEPTION 'retention metadata exceeds slot size' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN used_delta:=1; END IF;
    IF TG_TABLE_NAME='event_identities' THEN
      IF TG_OP='INSERT' AND NEW.kind IN ('terminal','recovery') THEN
        IF EXISTS(SELECT 1 FROM heimdall_retention.decision_identities d WHERE d.product_id=NEW.product_id
          AND d.environment=NEW.environment AND d.decision_id=NEW.decision_id AND d.resolution='pending') THEN
            reserved_delta:=-1;
        END IF;
      END IF;
    ELSIF TG_TABLE_NAME='decision_identities' THEN
        SELECT count(*) INTO members FROM heimdall_retention.event_identities i
          WHERE i.product_id=NEW.product_id AND i.environment=NEW.environment AND i.decision_id=NEW.decision_id AND i.kind IN ('terminal','recovery');
        IF TG_OP='INSERT' AND NEW.resolution='pending' THEN reserved_delta:=2-members;
        ELSIF TG_OP='UPDATE' AND OLD.resolution='pending' AND NEW.resolution<>'pending' THEN reserved_delta:=-(2-members);
        END IF;
    END IF;
    -- Updates serialize on this singleton; quota failure rolls back source rows.
    -- Exact retries and hold releases consume no new slot and refund nothing.
    UPDATE heimdall_retention.capacity SET used_rows=used_rows+used_delta,reserved_rows=reserved_rows+reserved_delta WHERE singleton;
    IF NOT FOUND THEN RAISE EXCEPTION 'retention capacity uninitialized' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_retention.guard_decision_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE source record; member record;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'retained decision cannot be deleted' USING ERRCODE='23514'; END IF;
    IF TG_OP='UPDATE' THEN
        IF (NEW.product_id,NEW.environment,NEW.decision_id,NEW.tenant_id,NEW.request_event_id,NEW.requested_at)
          IS DISTINCT FROM (OLD.product_id,OLD.environment,OLD.decision_id,OLD.tenant_id,OLD.request_event_id,OLD.requested_at) THEN
            RAISE EXCEPTION 'immutable retained request' USING ERRCODE='23514';
        END IF;
        IF NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
        IF OLD.resolution<>'pending' THEN RAISE EXCEPTION 'immutable retained resolution' USING ERRCODE='23514'; END IF;
    END IF;
    SELECT d.request_event_id,d.requested_at,d.resolution,d.terminal_event_id,d.resolved_at,r.recovery_event_id
      INTO source FROM heimdall.audit_decisions d JOIN heimdall_capacity.reservations r USING(product_id,environment,decision_id)
      WHERE d.product_id=NEW.product_id AND d.environment=NEW.environment AND d.decision_id=NEW.decision_id
      AND r.request_event_id=d.request_event_id AND r.resolution=d.resolution
      AND r.terminal_event_id IS NOT DISTINCT FROM d.terminal_event_id;
    IF NOT FOUND OR (NEW.request_event_id,NEW.requested_at,NEW.resolution,NEW.terminal_event_id,NEW.resolved_at,NEW.recovery_event_id)
      IS DISTINCT FROM (source.request_event_id,source.requested_at,source.resolution,source.terminal_event_id,source.resolved_at,source.recovery_event_id) THEN
        RAISE EXCEPTION 'retained decision source mismatch' USING ERRCODE='23514';
    END IF;
    FOR member IN SELECT event_id,kind,decision_id,tenant_id,recorded_at FROM heimdall_retention.event_identities
      WHERE product_id=NEW.product_id AND environment=NEW.environment
      AND event_id IN (NEW.request_event_id,NEW.terminal_event_id,NEW.recovery_event_id)
    LOOP
        IF member.decision_id IS DISTINCT FROM NEW.decision_id OR member.tenant_id IS DISTINCT FROM NEW.tenant_id
          OR (member.event_id=NEW.request_event_id AND (member.kind<>'request' OR member.recorded_at<>NEW.requested_at))
          OR (member.event_id=NEW.terminal_event_id AND (member.kind<>'terminal' OR member.recorded_at<>NEW.resolved_at))
          OR (member.event_id=NEW.recovery_event_id AND (member.kind<>'recovery' OR member.recorded_at<>NEW.resolved_at)) THEN
            RAISE EXCEPTION 'retained member mismatch' USING ERRCODE='23514';
        END IF;
    END LOOP;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_retention.guard_event_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE target record; reference_id text; reference_at bigint;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'hold history cannot be deleted' USING ERRCODE='23514'; END IF;
    IF TG_OP='UPDATE' THEN
        IF (NEW.product_id,NEW.environment,NEW.hold_id,NEW.event_id,NEW.tenant_id,NEW.placed_at,NEW.placement_event_id)
          IS DISTINCT FROM (OLD.product_id,OLD.environment,OLD.hold_id,OLD.event_id,OLD.tenant_id,OLD.placed_at,OLD.placement_event_id) THEN
            RAISE EXCEPTION 'immutable hold placement' USING ERRCODE='23514';
        END IF;
        IF NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
        IF OLD.released_at IS NOT NULL OR NEW.released_at IS NULL THEN
            RAISE EXCEPTION 'immutable hold release' USING ERRCODE='23514';
        END IF;
        reference_id:=NEW.release_event_id; reference_at:=NEW.released_at;
    ELSE
        IF NEW.released_at IS NOT NULL OR NEW.release_event_id IS NOT NULL THEN
            RAISE EXCEPTION 'new hold must be active' USING ERRCODE='23514';
        END IF;
        reference_id:=NEW.placement_event_id; reference_at:=NEW.placed_at;
    END IF;
    -- Future retirement must acquire this same identity lock before checking all
    -- member holds. A hold cannot be placed on an already absent payload.
    SELECT tenant_id,recorded_at INTO target FROM heimdall_retention.event_identities
      WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=NEW.event_id FOR UPDATE;
    IF NOT FOUND OR target.tenant_id IS DISTINCT FROM NEW.tenant_id OR NEW.placed_at<target.recorded_at THEN
        RAISE EXCEPTION 'hold target mismatch' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM heimdall.audit_events WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=NEW.event_id) THEN
        RAISE EXCEPTION 'hold target payload missing' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM heimdall_retention.event_identities i JOIN heimdall.audit_events e USING(product_id,environment,event_id)
      WHERE i.product_id=NEW.product_id AND i.environment=NEW.environment AND i.event_id=reference_id
      AND i.tenant_id IS NOT DISTINCT FROM NEW.tenant_id AND i.recorded_at=reference_at
      AND e.recorded_at=i.recorded_at AND e.payload_digest=i.payload_digest) THEN
        RAISE EXCEPTION 'hold audit reference mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_retention.guard_event_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE source record; expected_kind text; expected_decision text; expected_routing jsonb; matches bigint;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'retained identity cannot be deleted' USING ERRCODE='23514'; END IF;
    IF TG_OP='UPDATE' THEN
        IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'immutable event identity' USING ERRCODE='23514'; END IF;
        RETURN NEW;
    END IF;
    SELECT e.recorded_at,e.payload_digest,c.delivery_rows INTO source FROM heimdall.audit_events e
      JOIN heimdall_capacity.event_charges c USING(product_id,environment,event_id)
      WHERE e.product_id=NEW.product_id AND e.environment=NEW.environment AND e.event_id=NEW.event_id;
    IF NOT FOUND OR NEW.recorded_at IS DISTINCT FROM source.recorded_at OR NEW.payload_digest IS DISTINCT FROM source.payload_digest THEN
        RAISE EXCEPTION 'identity source mismatch' USING ERRCODE='23514';
    END IF;
    SELECT to_jsonb(ARRAY(SELECT sink_id FROM heimdall.audit_deliveries
      WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=NEW.event_id
      ORDER BY sink_id COLLATE "C")) INTO expected_routing;
    IF NEW.routing IS DISTINCT FROM expected_routing OR jsonb_array_length(expected_routing)<>source.delivery_rows THEN
        RAISE EXCEPTION 'identity routing mismatch' USING ERRCODE='23514';
    END IF;
    SELECT count(*),min(kind),min(decision_id) INTO matches,expected_kind,expected_decision FROM (
      SELECT 'request' AS kind,d.decision_id FROM heimdall.audit_decisions d
        WHERE d.product_id=NEW.product_id AND d.environment=NEW.environment AND d.request_event_id=NEW.event_id
      UNION ALL SELECT 'terminal',d.decision_id FROM heimdall.audit_decisions d
        WHERE d.product_id=NEW.product_id AND d.environment=NEW.environment AND d.terminal_event_id=NEW.event_id
      UNION ALL SELECT 'recovery',r.decision_id FROM heimdall_capacity.reservations r
        WHERE r.product_id=NEW.product_id AND r.environment=NEW.environment AND r.recovery_event_id=NEW.event_id
    ) bindings;
    IF matches>1 THEN RAISE EXCEPTION 'ambiguous decision identity' USING ERRCODE='23514'; END IF;
    IF matches=0 THEN expected_kind:='ordinary'; expected_decision:=NULL; END IF;
    IF NEW.kind IS DISTINCT FROM expected_kind OR NEW.decision_id IS DISTINCT FROM expected_decision THEN
        RAISE EXCEPTION 'identity decision mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_retention.guard_hold_purpose()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF NEW.purpose IS DISTINCT FROM OLD.purpose THEN
        RAISE EXCEPTION 'immutable hold purpose' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_retention.guard_retirement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE target record; decision record; members text[]; expected jsonb; verified bigint;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'retirement history cannot be deleted' USING ERRCODE='23514'; END IF;
    IF TG_OP='UPDATE' THEN
        IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'immutable retirement' USING ERRCODE='23514'; END IF;
        RETURN NEW;
    END IF;
    SELECT * INTO target FROM heimdall_retention.event_identities WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=NEW.target_event_id;
    IF NOT FOUND OR target.tenant_id IS DISTINCT FROM NEW.tenant_id THEN RAISE EXCEPTION 'retirement target mismatch' USING ERRCODE='23514'; END IF;
    IF target.kind='ordinary' THEN members:=ARRAY[target.event_id];
    ELSIF target.kind='request' THEN
        SELECT * INTO decision FROM heimdall_retention.decision_identities WHERE product_id=NEW.product_id AND environment=NEW.environment AND decision_id=target.decision_id;
        IF NOT FOUND OR decision.resolution='pending' OR decision.tenant_id IS DISTINCT FROM NEW.tenant_id OR decision.request_event_id<>target.event_id THEN
            RAISE EXCEPTION 'retirement decision incomplete' USING ERRCODE='23514';
        END IF;
        members:=array_remove(ARRAY[decision.request_event_id,decision.terminal_event_id,decision.recovery_event_id],NULL);
    ELSE RAISE EXCEPTION 'retirement requires whole group' USING ERRCODE='23514';
    END IF;
    SELECT to_jsonb(array_agg(id ORDER BY id COLLATE "C")) INTO expected FROM unnest(members) id;
    IF NEW.member_event_ids IS DISTINCT FROM expected OR NEW.administration_event_id=ANY(members) OR NEW.retired_at<NEW.retain_for_ms THEN
        RAISE EXCEPTION 'retirement members or time mismatch' USING ERRCODE='23514';
    END IF;
    PERFORM event_id FROM heimdall_retention.event_identities WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=ANY(members) ORDER BY event_id COLLATE "C" FOR UPDATE;
    PERFORM event_id FROM heimdall.audit_deliveries WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=ANY(members) ORDER BY event_id COLLATE "C",sink_id COLLATE "C" FOR UPDATE;
    IF EXISTS(SELECT 1 FROM heimdall_retention.event_holds WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=ANY(members) AND released_at IS NULL) THEN
        RAISE EXCEPTION 'retirement group held' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO verified FROM heimdall_retention.event_identities i JOIN heimdall.audit_events e USING(product_id,environment,event_id)
      JOIN heimdall_capacity.event_charges c USING(product_id,environment,event_id)
      WHERE i.product_id=NEW.product_id AND i.environment=NEW.environment AND i.event_id=ANY(members)
      AND i.tenant_id IS NOT DISTINCT FROM NEW.tenant_id AND i.recorded_at=e.recorded_at AND i.payload_digest=e.payload_digest
      AND i.recorded_at<=NEW.retired_at-NEW.retain_for_ms AND c.envelope_bytes=octet_length(e.event::text)
      AND i.routing=to_jsonb(ARRAY(SELECT sink_id FROM heimdall.audit_deliveries d WHERE d.product_id=i.product_id AND d.environment=i.environment AND d.event_id=i.event_id ORDER BY sink_id COLLATE "C"))
      AND c.delivery_rows=jsonb_array_length(i.routing);
    IF verified<>cardinality(members) OR EXISTS(SELECT 1 FROM heimdall.audit_deliveries WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=ANY(members)
      AND (state<>'delivered' OR delivered_at IS NULL OR delivered_at>NEW.retired_at-NEW.retain_for_ms)) THEN
        RAISE EXCEPTION 'retirement history ineligible' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM heimdall_retention.event_identities i JOIN heimdall.audit_events e USING(product_id,environment,event_id)
      WHERE i.product_id=NEW.product_id AND i.environment=NEW.environment AND i.event_id=NEW.administration_event_id
      AND i.tenant_id IS NOT DISTINCT FROM NEW.tenant_id AND i.recorded_at=NEW.retired_at AND e.recorded_at=i.recorded_at AND e.payload_digest=i.payload_digest) THEN
        RAISE EXCEPTION 'retirement audit reference mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_retention.initialize_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    -- DDL locks and drained writers are required while adopting existing rows.
    IF EXISTS(SELECT 1 FROM heimdall_retention.retirements r WHERE octet_length(to_jsonb(r)::text)>8192)
      OR EXISTS(SELECT 1 FROM heimdall_retention.event_identities i WHERE octet_length(to_jsonb(i)::text)>8192)
      OR EXISTS(SELECT 1 FROM heimdall_retention.decision_identities d WHERE octet_length(to_jsonb(d)::text)>8192)
      OR EXISTS(SELECT 1 FROM heimdall_retention.event_holds h WHERE octet_length(to_jsonb(h)::text)>8192) THEN
        RAISE EXCEPTION 'retention metadata exceeds slot size' USING ERRCODE='23514';
    END IF;
    SELECT (SELECT count(*) FROM heimdall_retention.retirements)+(SELECT count(*) FROM heimdall_retention.event_identities)+(SELECT count(*) FROM heimdall_retention.decision_identities)+(SELECT count(*) FROM heimdall_retention.event_holds) INTO NEW.used_rows;
    SELECT coalesce(sum(2-(SELECT count(*) FROM heimdall_retention.event_identities i
      WHERE i.product_id=d.product_id AND i.environment=d.environment AND i.decision_id=d.decision_id AND i.kind IN ('terminal','recovery'))),0)
      INTO NEW.reserved_rows FROM heimdall_retention.decision_identities d WHERE d.resolution='pending';
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION heimdall_retention.verify_retirement_commit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF EXISTS(SELECT 1 FROM heimdall.audit_events WHERE product_id=NEW.product_id AND environment=NEW.environment AND NEW.member_event_ids ? event_id)
      OR EXISTS(SELECT 1 FROM heimdall_retention.event_holds WHERE product_id=NEW.product_id AND environment=NEW.environment AND NEW.member_event_ids ? event_id AND released_at IS NULL)
      OR NOT EXISTS(SELECT 1 FROM heimdall.audit_events WHERE product_id=NEW.product_id AND environment=NEW.environment AND event_id=NEW.administration_event_id) THEN
        RAISE EXCEPTION 'retirement transaction incomplete' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$
